from lib import *
# ============ Present simple ============
T = "Present simple"
mc(T,"A2.1",1,"Choose the correct form: My parents ___ in a small village.","live",["lives","living","are live"],"*They* + base verb: *they live*.","*They* + pamatforma: *they live*.")
mc(T,"A2.1",1,"Choose the correct form: Sam ___ his teeth after breakfast.","brushes",["brush","brushing","is brush"],"Verbs ending in *-sh* add *-es*: *he brushes*.","Darbības vārdiem ar *-sh* pievieno *-es*: *he brushes*.")
gp(T,"A2.1",3,"My sister ___ a red bike. (have)","has","*He, she, it*: *have → has*.","*He, she, it*: *have → has*.")
gp(T,"A2.1",3,"Mia ___ to school by bus. (go)","goes","*Go* adds *-es*: *she goes*.","*Go* pievieno *-es*: *she goes*.")
tx(T,"A2.1",3,"Make it negative: My brother likes cold milk.",["My brother doesn't like cold milk.","My brother does not like cold milk."],"With *he, she, it* use *doesn't* + base verb.","Ar *he, she, it* lieto *doesn't* + pamatforma.")
tx(T,"A2.1",3,"Make a question: Your friends play chess.","Do your friends play chess?","*Friends* is plural, so *Do* + subject + base verb.","*Friends* ir daudzskaitlī, tāpēc *Do* + priekšmets + pamatforma.")
mt(T,"A2.1",2,"Match each beginning with its ending.",[("He plays","football on Saturdays."),("She teaches","English at a school."),("They live","near the park."),("We watch","TV in the evening.")],"Add *-s* after *he / she / it*: *plays, teaches*. No *-s* after *they / we*.","Pēc *he / she / it* pievieno *-s*: *plays, teaches*. Pēc *they / we* bez *-s*.")
od(T,"A2.1",3,"Put the words in order. Use the present simple.","my grandmother never drinks coffee","The adverb *never* goes before the main verb.","Apstākļa vārds *never* ir pirms darbības vārda.")
mc(T,"A2.1",4,"At work: which sentence is NOT correct?","He don't like his new job.",["He doesn't like his new job.","They don't like their new jobs.","She likes her new job."],"With *he* we use *doesn't*, not *don't*.","Ar *he* lieto *doesn't*, nevis *don't*.")
mc(T,"A2.1",2,"Choose the short answer: 'Does Tom live here?'","No, he doesn't.",["No, he don't.","No, he isn't.","No, he not does."],"Short answer: *No, he doesn't.*","Īsā atbilde: *No, he doesn't.*")
mc(T,"A2.2",1,"Choose the correct question: ___ usually have for lunch?","What do you",["What does you","What are you","What you do"],"Question: *What* + *do* + *you* + base verb.","Jautājums: *What* + *do* + *you* + pamatforma.")
mc(T,"A2.2",2,"Choose the correct sentence.","My brother never eats breakfast.",["My brother eats never breakfast.","My brother never eat breakfast.","Never my brother eats breakfast."],"*Never* goes before the main verb, and *he* needs *-s*.","*Never* ir pirms darbības vārda, un *he* vajag *-s*.")
gp(T,"A2.2",3,"How often ___ your parents ___ the doctor? (visit)","do / visit","*Parents* is plural: *do* + base verb.","*Parents* ir daudzskaitlī: *do* + pamatforma.")
gp(T,"A2.2",3,"She ___ her homework on Sunday evening, never on Friday. (do)","does","*Do* with *she* becomes *does*.","*Do* ar *she* kļūst par *does*.")
tx(T,"A2.2",3,"Make a question with Where: Mark works in a hospital.","Where does Mark work?","*Where* + *does* + subject + base verb.","*Where* + *does* + priekšmets + pamatforma.")
tx(T,"A2.2",3,"Make it negative: The shop opens on Sundays.",["The shop doesn't open on Sundays.","The shop does not open on Sundays."],"*Shop* is *it*: *doesn't open*.","*Shop* ir *it*: *doesn't open*.")
od(T,"A2.2",3,"Put the words in order. Ask about a habit.","how often do you visit your grandparents","*How often* + *do* + subject + base verb.","*How often* + *do* + priekšmets + pamatforma.")
mt(T,"A2.2",2,"Match each question with its short answer.",[("Do you like fish?","Yes, I do."),("Does she work here?","No, she doesn't."),("Do they speak French?","No, they don't."),("Does it rain a lot?","Yes, it does.")],"Answer with the same helping verb: *do / does*.","Atbild ar to pašu palīgdarbības vārdu: *do / does*.")
mc(T,"A2.2",4,"Which question is NOT correct?","Where does your brother works?",["Where does your brother work?","What time do the shops open?","Does she like jazz?"],"After *does* the verb has no *-s*: *does your brother work*.","Pēc *does* darbības vārdam nav *-s*: *does your brother work*.")
mc(T,"A2.2",3,"Choose the correct option: In my country, the shops ___ at 9 a.m. on weekdays.","open",["opens","is open","opening"],"*Shops* is plural: *they open*.","*Shops* ir daudzskaitlī: *they open*.")
# ============ Present continuous ============
T = "Present continuous"
mc(T,"A2.1",1,"Choose the correct form: Be quiet! The baby ___ .","is sleeping",["sleeps","sleeping","is sleep"],"Now: *is* + verb + *-ing*.","Tagad: *is* + darbības vārds + *-ing*.")
mc(T,"A2.1",1,"Choose the correct form: We ___ lunch at the moment.","are having",["have","are have","having"],"*At the moment* = now: *are having*.","*At the moment* = tagad: *are having*.")
gp(T,"A2.1",3,"Look! It ___ outside. (rain)","is raining","Now: *is raining*.","Tagad: *is raining*.")
gp(T,"A2.1",3,"My friends ___ football in the park now. (play)","are playing","*Friends* is plural: *are playing*.","*Friends* ir daudzskaitlī: *are playing*.")
tx(T,"A2.1",3,"Make it negative: Dad is washing the car.",["Dad isn't washing the car.","Dad is not washing the car."],"Put *not* after *is*.","Liec *not* aiz *is*.")
tx(T,"A2.1",3,"Make a question: The children are swimming.","Are the children swimming?","Put *are* before the subject.","Liec *are* pirms priekšmeta.")
od(T,"A2.1",3,"Put the words in order. Say what is happening now.","the students are writing a test","Subject + *are* + verb + *-ing*.","Priekšmets + *are* + darbības vārds + *-ing*.")
mc(T,"A2.1",4,"At the bus stop: which sentence is NOT correct?","She is wait for the bus.",["She is waiting for the bus.","They are waiting for the bus.","I am waiting for the bus."],"After *is* the verb needs *-ing*: *is waiting*.","Pēc *is* darbības vārdam vajag *-ing*: *is waiting*.")
mc(T,"A2.2",2,"Which sentence is about a temporary situation?","I'm staying with my uncle this week.",["I live with my uncle.","My uncle lives near here.","I stay with my uncle every summer."],"The present continuous shows something temporary: *this week*.","Tagadnes ilgstošā forma parāda kaut ko pagaidu: *this week*.")
mc(T,"A2.2",3,"Choose the correct option: Why ___ you ___ a coat? It is warm today.","are / wearing",["do / wear","is / wearing","are / wear"],"*Why are you wearing* asks about now.","*Why are you wearing* jautā par tagadni.")
gp(T,"A2.2",3,"What ___ you ___ at the moment? (read)","are / reading","*Are* + subject + verb + *-ing*.","*Are* + priekšmets + darbības vārds + *-ing*.")
gp(T,"A2.2",3,"Tom ___ to his sister on the phone right now. (talk)","is talking","*Right now* = present continuous.","*Right now* = tagadnes ilgstošā forma.")
mt(T,"A2.2",2,"Match each question with its answer.",[("What are you doing?","I'm baking a cake."),("Is it raining?","No, it isn't."),("Who is she talking to?","Her teacher."),("Are they waiting for us?","Yes, they are.")],"Short answers repeat *am / is / are*.","Īsās atbildes atkārto *am / is / are*.")
mc(T,"A2.2",3,"Choose the correct option: My English ___ better these days.","is getting",["gets","getting","is get"],"*These days* shows a change: *is getting*.","*These days* parāda pārmaiņu: *is getting*.")
mc(T,"A2.2",4,"In the office: which sentence is NOT correct?","I'm not understanding this exercise.",["I don't understand this exercise.","She is making coffee now.","They are studying for a test."],"*Understand* is a state verb: we say *I don't understand*.","*Understand* ir stāvokļa darbības vārds: saka *I don't understand*.")
tx(T,"A2.2",3,"Make a question with What: He is cooking.","What is he cooking?","*What* + *is* + subject + verb + *-ing*.","*What* + *is* + priekšmets + darbības vārds + *-ing*.")
# ============ Past simple ============
T = "Past simple"
mc(T,"A2.1",1,"Choose the correct form: We ___ a film last night.","watched",["watch","watching","did watched"],"Finished time: add *-ed*: *watched*.","Pabeigts laiks: pievieno *-ed*: *watched*.")
mc(T,"A2.1",1,"Choose the correct form: Lisa ___ her bag on the bus yesterday.","lost",["losed","lose","loses"],"*Lose* is irregular: *lost*.","*Lose* ir neregulārs: *lost*.")
gp(T,"A2.1",3,"I ___ my grandmother last Sunday. (visit)","visited","Add *-ed*: *visited*.","Pievieno *-ed*: *visited*.")
gp(T,"A2.1",3,"He ___ a letter to his friend. (write)","wrote","*Write* is irregular: *wrote*.","*Write* ir neregulārs: *wrote*.")
gp(T,"A2.1",3,"They ___ to the party because they were tired. (not / go)","didn't go | did not go","*Didn't* + base verb.","*Didn't* + pamatforma.")
tx(T,"A2.1",3,"Make a question: She bought a new coat.","Did she buy a new coat?","*Did* + subject + base verb.","*Did* + priekšmets + pamatforma.")
od(T,"A2.1",3,"Put the words in order. Say what you did yesterday.","i met my friends in the park","Subject + past verb + the rest.","Priekšmets + pagātnes forma + pārējais.")
mt(T,"A2.1",2,"Match each verb with its past form.",[("eat","ate"),("see","saw"),("take","took"),("come","came")],"These verbs are irregular: learn each past form.","Šie darbības vārdi ir neregulāri: iemācies katru pagātnes formu.")
mc(T,"A2.1",4,"At school: which sentence is NOT correct?","She didn't liked the film.",["She didn't like the film.","She liked the film.","They didn't like the film."],"After *didn't* the verb stays in the base form: *like*.","Pēc *didn't* darbības vārds paliek pamatformā: *like*.")
mc(T,"A2.2",3,"Choose the correct option: Where ___ your parents ___ last year?","did / live",["did / lived","do / live","were / live"],"*Did* + subject + base verb.","*Did* + priekšmets + pamatforma.")
mc(T,"A2.2",3,"Choose the correct option: We ___ very tired after the long walk.","were",["was","did","have"],"*Were* is the past of *are* (*we were*).","*Were* ir *are* pagātne (*we were*).")
gp(T,"A2.2",3,"It ___ cold, so we ___ inside. (be / stay)","was / stayed","*Be* is *was* with *it*; *stay + -ed*.","*Be* ar *it* ir *was*; *stay + -ed*.")
gp(T,"A2.2",3,"How much money ___ you ___ at the shop? (spend)","did / spend","*Did* + subject + base verb.","*Did* + priekšmets + pamatforma.")
tx(T,"A2.2",3,"Make it negative: We watched TV last night.",["We didn't watch TV last night.","We did not watch TV last night."],"*Didn't* + base verb.","*Didn't* + pamatforma.")
tx(T,"A2.2",3,"Make a question with Why: He left early.","Why did he leave early?","*Why* + *did* + subject + base verb.","*Why* + *did* + priekšmets + pamatforma.")
od(T,"A2.2",3,"Put the words in order. Ask about last weekend.","what did you do last weekend","*What* + *did* + subject + base verb.","*What* + *did* + priekšmets + pamatforma.")
mc(T,"A2.2",4,"At the gym: which question is NOT correct?","Did you went to the gym?",["Did you go to the gym?","Where did you go?","Did she call you?"],"After *did* the verb is in the base form: *go*.","Pēc *did* darbības vārds ir pamatformā: *go*.")
# ============ Past continuous ============
T = "Past continuous"
mc(T,"A2.2",1,"Choose the correct form: I ___ a book when the phone rang.","was reading",["read","am reading","were reading"],"An action in progress in the past: *was / were* + *-ing*.","Darbība, kas pagātnē norisinājās: *was / were* + *-ing*.")
mc(T,"A2.2",2,"Choose the correct form: They ___ football at five o'clock yesterday.","were playing",["was playing","played","are playing"],"*They* + *were* + verb + *-ing*.","*They* + *were* + darbības vārds + *-ing*.")
gp(T,"A2.2",3,"At 9 p.m. she ___ a film. (watch)","was watching","A moment in the past: *was watching*.","Brīdis pagātnē: *was watching*.")
gp(T,"A2.2",3,"We ___ dinner when the lights went out. (have)","were having","The long action: *were having*.","Garā darbība: *were having*.")
tx(T,"A2.2",3,"Make it negative: I was sleeping.",["I wasn't sleeping.","I was not sleeping."],"Put *not* after *was*.","Liec *not* aiz *was*.")
tx(T,"A2.2",3,"Make a question: They were waiting for us.","Were they waiting for us?","Put *were* before the subject.","Liec *were* pirms priekšmeta.")
mc(T,"A2.2",4,"In the park: which sentence is NOT correct?","He were running with his dog.",["He was running with his dog.","They were running with their dog.","I was running with my dog."],"*He* goes with *was*, not *were*.","*He* lieto ar *was*, nevis *were*.")
od(T,"A2.2",3,"Put the words in order. Say what was happening.","the children were playing in the garden","Subject + *were* + verb + *-ing* + place.","Priekšmets + *were* + darbības vārds + *-ing* + vieta.")
mc(T,"A2.2",3,"Choose the correct option: While I ___ , my brother was cooking dinner.","was studying",["studied","study","were studying"],"Two actions at the same time: *while* + *was studying*.","Divas darbības vienlaikus: *while* + *was studying*.")
# ============ Present perfect ============
T = "Present perfect"
mc(T,"A2.2",1,"Choose the correct form: She has ___ in three countries.","lived",["live","living","lives"],"*Has* + past participle: *has lived*.","*Has* + pagātnes divdabis: *has lived*.")
mc(T,"A2.2",2,"Choose the correct word: Have you ___ been to Paris?","ever",["yesterday","ago","last"],"*Ever* asks about any time in your life.","*Ever* jautā par jebkuru laiku dzīvē.")
gp(T,"A2.2",3,"We ___ our homework yet. (not / finish)","haven't finished | have not finished","*Yet* goes with the present perfect in negatives.","*Yet* ar *present perfect* lieto noliegumos.")
gp(T,"A2.2",3,"He ___ a new car. (just / buy)","has just bought","*Just* goes between *has* and the participle.","*Just* iet starp *has* un divdabi.")
tx(T,"A2.2",3,"Make a question with ever: You have eaten sushi.","Have you ever eaten sushi?","*Have* + subject + *ever* + participle.","*Have* + priekšmets + *ever* + divdabis.")
tx(T,"A2.2",3,"Make it negative: I have seen him.",["I haven't seen him.","I have not seen him."],"Put *not* after *have*.","Liec *not* aiz *have*.")
mc(T,"A2.2",4,"About travel: which sentence is NOT correct?","I have been to Spain last year.",["I have been to Spain twice.","I went to Spain last year.","Have you ever been to Spain?"],"With *last year* (a finished time) we use the past simple.","Ar *last year* (pabeigts laiks) lieto vienkāršo pagātni.")
mc(T,"A2.2",2,"Choose the correct meaning: 'Mum has gone to the shop.'","She is at the shop now.",["She is back home now.","She will go to the shop tomorrow.","She went to the shop last year."],"*Has gone* = she went and is still there.","*Has gone* = viņa aizgāja un vēl ir tur.")
od(T,"A2.2",3,"Put the words in order. Say you did not do it yet.","i haven't called my mother yet","*Yet* goes at the end.","*Yet* ir teikuma beigās.")
mt(T,"A2.2",2,"Match each question with its short answer.",[("Have you finished?","Yes, I have."),("Has he called?","No, he hasn't."),("Have they arrived yet?","Not yet."),("Has she ever lived abroad?","Yes, she has.")],"Short answers use *have / has*.","Īsās atbildes lieto *have / has*.")
# ============ Future ============
T = "Future: will, going to, present continuous"
mc(T,"A2.1",1,"Choose the correct form: We ___ visit my aunt on Sunday.","are going to",["go to","going to","will to"],"A plan: *are going to* + base verb.","Plāns: *are going to* + pamatforma.")
gp(T,"A2.1",3,"She ___ a new phone next week. (buy)","is going to buy","A plan: *is going to buy*.","Plāns: *is going to buy*.")
gp(T,"A2.1",3,"I ___ my homework tonight. (not / do)","'m not going to do | am not going to do","Negative plan: *am not going to*.","Noliegts plāns: *am not going to*.")
tx(T,"A2.1",3,"Make a question: You are going to cook dinner.","Are you going to cook dinner?","Put *are* before the subject.","Liec *are* pirms priekšmeta.")
od(T,"A2.1",3,"Put the words in order. Say your plan.","we are going to travel by train","Subject + *are going to* + verb.","Priekšmets + *are going to* + darbības vārds.")
mc(T,"A2.1",4,"About plans: which sentence is NOT correct?","He going to play tennis tomorrow.",["He is going to play tennis tomorrow.","They are going to play tennis tomorrow.","I am going to play tennis tomorrow."],"We need *is / am / are* before *going to*.","Pirms *going to* vajag *is / am / are*.")
mc(T,"A2.2",3,"Choose the correct option: You are cold? OK, I ___ the window.","'ll close",["am closing","close","am going to close"],"A decision at the moment of speaking: *'ll* + base verb.","Lēmums runāšanas brīdī: *'ll* + pamatforma.")
mc(T,"A2.2",3,"Choose the correct option: Look at that man! He ___ fall off the ladder.","is going to",["will to","goes to","is"],"We can see it now, so we use *is going to*.","Mēs to redzam tagad, tāpēc lieto *is going to*.")
gp(T,"A2.2",3,"I think the match ___ very exciting. (be)","will be","*I think* + *will* for a prediction.","*I think* + *will* prognozei.")
gp(T,"A2.2",3,"We ___ our grandparents on Saturday. We have bought the tickets. (visit)","are visiting","A fixed arrangement: present continuous.","Norunāts pasākums: tagadnes ilgstošā forma.")
tx(T,"A2.2",3,"Make it negative: It will rain tomorrow.",["It won't rain tomorrow.","It will not rain tomorrow."],"Negative of *will* is *won't*.","*Will* noliegums ir *won't*.")
mc(T,"A2.2",2,"Which sentence is an arrangement with a time?","I'm meeting Jack at six.",["I'll probably be late.","It might snow.","I hope to travel."],"An arrangement: present continuous + a time.","Norunāts pasākums: tagadnes ilgstošā forma + laiks.")
mt(T,"A2.2",2,"Match each situation with the best sentence.",[("You see black clouds.","It's going to rain."),("The phone is ringing.","I'll answer it."),("You have bought two tickets.","We're flying to Rome."),("You are not sure.","I think it will be fine.")],"*Going to* = evidence, *'ll* = decision now, present continuous = arrangement, *think ... will* = opinion.","*Going to* = pierādījumi, *'ll* = lēmums tagad, tagadnes ilgstošā = norunāts, *think ... will* = viedoklis.")
# ============ Passives ============
T = "Present simple passive"
mc(T,"A2.2",1,"Choose the correct form: Tea ___ in India.","is grown",["grows","is grow","are grown"],"Passive: *is / are* + past participle.","Pasīvs: *is / are* + pagātnes divdabis.")
mc(T,"A2.2",1,"Choose the correct form: These shoes ___ in Italy.","are made",["is made","make","are make"],"*Shoes* is plural: *are made*.","*Shoes* ir daudzskaitlī: *are made*.")
gp(T,"A2.2",3,"Parcels ___ to our office every morning. (deliver)","are delivered","Passive: *are delivered*.","Pasīvs: *are delivered*.")
gp(T,"A2.2",3,"The classrooms ___ every evening. (clean)","are cleaned","Passive: *are cleaned*.","Pasīvs: *are cleaned*.")
tx(T,"A2.2",3,"Make it passive: People speak French in Canada.","French is spoken in Canada.","The object becomes the subject: *French is spoken*.","Papildinātājs kļūst par priekšmetu: *French is spoken*.")
tx(T,"A2.2",3,"Make it negative: Cars are sold here.",["Cars aren't sold here.","Cars are not sold here."],"Put *not* after *are*.","Liec *not* aiz *are*.")
od(T,"A2.2",3,"Put the words in order. Use the passive.","rice is grown in many countries","Subject + *is* + past participle + place.","Priekšmets + *is* + divdabis + vieta.")
mc(T,"A2.2",4,"In the factory: which sentence is NOT correct?","The boxes is packed by hand.",["The boxes are packed by hand.","The machine is turned off at night.","These cars are tested every week."],"*Boxes* is plural: *are packed*.","*Boxes* ir daudzskaitlī: *are packed*.")
mc(T,"A2.2",3,"Choose the correct question: ___ English spoken in your country?","Is",["Does","Are","Do"],"Passive question: *Is* + subject + participle.","Pasīva jautājums: *Is* + priekšmets + divdabis.")
T = "Past simple passive"
mc(T,"A2.2",1,"Choose the correct form: The window ___ by a ball.","was broken",["broke","is broken","were broken"],"Passive past: *was / were* + participle.","Pasīvs pagātnē: *was / were* + divdabis.")
mc(T,"A2.2",1,"Choose the correct form: These photos ___ last summer.","were taken",["was taken","took","are taken"],"*Photos* is plural: *were taken*.","*Photos* ir daudzskaitlī: *were taken*.")
gp(T,"A2.2",3,"The room ___ yesterday. (clean)","was cleaned","Passive past: *was cleaned*.","Pasīvs pagātnē: *was cleaned*.")
gp(T,"A2.2",3,"The books ___ by a famous writer. (write)","were written","*Write* is irregular, but the participle is *written*.","*Write* ir neregulārs, divdabis ir *written*.")
tx(T,"A2.2",3,"Make it passive: Someone stole my bike.","My bike was stolen.","We do not say who did it: *was stolen*.","Nesakām, kas to izdarīja: *was stolen*.")
tx(T,"A2.2",3,"Make it negative: The letter was sent.",["The letter wasn't sent.","The letter was not sent."],"Put *not* after *was*.","Liec *not* aiz *was*.")
od(T,"A2.2",3,"Put the words in order. Use the passive.","the house was built in 1950","Subject + *was* + participle + time.","Priekšmets + *was* + divdabis + laiks.")
mc(T,"A2.2",4,"About history: which sentence is NOT correct?","The castle was build in 1200.",["The castle was built in 1200.","The walls were painted white.","The bridge was opened in May."],"After *was* we need the participle: *built*.","Pēc *was* vajag divdabi: *built*.")
mc(T,"A2.2",3,"Choose the correct option: When ___ the museum ___ ?","was / opened",["did / opened","was / open","is / opened"],"Passive question: *was* + subject + participle.","Pasīva jautājums: *was* + priekšmets + divdabis.")
# ============ Conditionals ============
T = "Zero conditional (if + present, present)"
mc(T,"A2.2",1,"Choose the correct form: If water gets very cold, it ___ .","freezes",["will freeze","froze","freeze"],"Always true: present simple in both parts.","Vienmēr patiess: abās daļās vienkāršā tagadne.")
mc(T,"A2.2",1,"Choose the correct form: If I ___ tired, I go to bed early.","am",["will be","was","would be"],"Zero conditional: *if* + present simple.","Nulles nosacījums: *if* + vienkāršā tagadne.")
gp(T,"A2.2",3,"If you ___ a plant, it dies. (not / water)","don't water | do not water","Present simple in the *if* part.","Vienkāršā tagadne *if* daļā.")
gp(T,"A2.2",3,"When the sun ___ , the snow melts. (come out)","comes out","*When* works like *if* for things that always happen.","*When* darbojas kā *if* lietām, kas notiek vienmēr.")
tx(T,"A2.2",3,"Join with If: You press this button. The door opens.",["If you press this button, the door opens.","The door opens if you press this button."],"Present simple in both parts.","Abās daļās vienkāršā tagadne.")
mc(T,"A2.2",4,"In art class: which sentence is NOT correct?","If you mix red and white, you gets pink.",["If you mix red and white, you get pink.","If you mix blue and yellow, you get green.","When you mix black and white, you get grey."],"*You* takes *get*, not *gets*.","*You* lieto ar *get*, nevis *gets*.")
od(T,"A2.2",3,"Put the words in order. Say what always happens.","if people don't sleep they feel tired","*If* + present simple, present simple.","*If* + vienkāršā tagadne, vienkāršā tagadne.")
T = "First conditional (if + present, will)"
mc(T,"A2.2",1,"Choose the correct form: If we hurry, we ___ the bus.","will catch",["catch","caught","would catch"],"First conditional: *will* + base verb in the result.","Pirmais nosacījums: rezultātā *will* + pamatforma.")
mc(T,"A2.2",2,"Choose the correct form: If the weather ___ good, we will have a picnic.","is",["will be","was","would be"],"After *if* we use the present simple, not *will*.","Pēc *if* lieto vienkāršo tagadni, nevis *will*.")
gp(T,"A2.2",3,"If you ___ me your number, I'll call you tonight. (give)","give","Present simple after *if*.","Vienkāršā tagadne pēc *if*.")
